// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        // Fix the chain so the outcome of play() is determined by the fuzzed timestamp.
        vm.roll(1);
        uint256 random = uint256(keccak256(abi.encodePacked(ts, block.prevrandao))) % 2;
        // Restrict (widely, over the fuzzer's timestamp space) to the losing outcome,
        // where the pot accumulates rather than paying out.
        vm.assume(random == 1);

        vm.warp(ts);
        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        // General rule: after a losing play, the pot holds exactly one ticket deposit
        // (10 wei of value in pot and in the contract's balance) — never more.
        assertTrue(c.pot() == 10 && address(c).balance == 10);
    }
}
